$filters=['period_key'=>trim((string)($_GET['period_key']??'')),'report_type'=>trim((string)($_GET['report_type']??'')),'submitter_id'=>(int)($_GET['submitter_id']??0),'status'=>trim((string)($_GET['status']??'')),'unit_id'=>(int)($_GET['unit_id']??0),'date_from'=>trim((string)($_GET['date_from']??'')),'date_to'=>trim((string)($_GET['date_to']??''))];
$rows=ManagementReportsRepository::list($filters);$allRows=ManagementReportsRepository::list();$stats=ManagementReportsRepository::stats($allRows);
if(($_GET['action']??'')==='excel'){
    $fieldRows=Database::fetchAll('SELECT f.id,f.label,f.field_type,sec.sort_order section_sort,f.sort_order field_sort FROM management_report_fields f JOIN management_report_sections sec ON sec.id=f.section_id JOIN management_report_templates t ON t.id=sec.template_id WHERE f.active=1 AND sec.active=1 ORDER BY sec.sort_order,f.sort_order,f.id');$headers=['شناسه','نوع گزارش','دوره','ثبت‌کننده','واحد','وضعیت','تاریخ ثبت'];foreach($fieldRows as $field)$headers[]=$field['label'];$sheet=[$headers];
    foreach($rows as $row){$values=Database::fetchAll('SELECT field_id,value_text,value_number,value_json FROM management_report_values WHERE submission_id=?',[(int)$row['id']]);$map=[];foreach($values as $value)$map[(int)$value['field_id']]=$value;$line=[$row['id'],ManagementReportsRepository::TYPES[$row['report_type']]??$row['report_type'],$row['period_title'],$row['submitter_name'],$row['unit_title'],ManagementReportsRepository::STATUSES[$row['status']]??$row['status'],$row['created_at']];foreach($fieldRows as $field){$value=$map[(int)$field['id']]??null;$line[]=$value?($value['value_json']!==null?self_join_report_json($value['value_json']):($value['value_number']!==null?$value['value_number']:$value['value_text'])):'';}$sheet[]=$line;}
    CeoDashboardExcel::output(['گزارشات مدیران'=>$sheet],'management-reports-'.date('Y-m-d').'.xlsx');
}
function self_join_report_json(?string $json): string{$rows=json_decode((string)$json,true);if(!is_array($rows))return '';$parts=[];foreach($rows as $row)$parts[]=is_array($row)?implode(' | ',array_values($row)):(string)$row;return implode("\n",$parts);}
