<section class="card no-print"><form method="get" class="mr-filter"><label class="form-field"><span>دوره</span><select name="period_key"><option value="">همه دوره‌ها</option><?php foreach($periods as $period):?><option value="<?=e($period['period_key'])?>" <?=$filters['period_key']===$period['period_key']?'selected':''?>><?=e($period['period_title'])?></option><?php endforeach?></select></label><label class="form-field"><span>نوع گزارش</span><select name="report_type"><option value="">همه انواع</option><?php foreach(ManagementReportsRepository::TYPES as $type=>$label):?><option value="<?=$type?>" <?=$filters['report_type']===$type?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><label class="form-field"><span>ثبت‌کننده</span><select name="submitter_id"><option value="">همه</option><?php foreach($users as $user):?><option value="<?=$user['id']?>" <?=$filters['submitter_id']===(int)$user['id']?'selected':''?>><?=e($user['name'].' — '.($user['employee_no']?:'بدون شماره'))?></option><?php endforeach?></select></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="">همه</option><?php foreach(ManagementReportsRepository::STATUSES as $status=>$label):?><option value="<?=$status?>" <?=$filters['status']===$status?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><label class="form-field"><span>واحد</span><select name="unit_id"><option value="">همه</option><?php foreach($units as $unit):?><option value="<?=$unit['id']?>" <?=$filters['unit_id']===(int)$unit['id']?'selected':''?>><?=e($unit['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>از تاریخ</span><input type="date" name="date_from" value="<?=e($filters['date_from'])?>"></label><label class="form-field"><span>تا تاریخ</span><input type="date" name="date_to" value="<?=e($filters['date_to'])?>"></label><div class="mr-actions"><button class="btn btn-primary">اعمال فیلتر</button><a class="btn" href="/admin/management-reports.php">پاکسازی</a><a class="btn" href="?<?=e($query.($query?'&':'').'action=excel')?>">خروجی Excel</a></div></form></section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>گزارش</th><th>دوره</th><th>ثبت‌کننده / واحد</th><th>وضعیت</th><th>آخرین تغییر</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e(ManagementReportsRepository::TYPES[$row['report_type']]??$row['template_title'])?></strong><small>#<?=$row['id']?></small></td><td><?=e($row['period_title'])?></td><td><?=e($row['submitter_name'])?><small><?=e($row['unit_title']?:'بدون واحد')?></small></td><td><span class="mr-status mr-status-<?=e($row['status'])?>"><?=e(ManagementReportsRepository::STATUSES[$row['status']]??'')?></span></td><td><?=e(format_jalali_datetime($row['updated_at']))?></td><td><div class="mr-actions"><a class="btn btn-small" href="/admin/management-report-view.php?id=<?=$row['id']?>">جزئیات</a><?php if((int)$row['submitter_id']===(int)Auth::user()['id']&&in_array($row['status'],['draft','returned'],true)):?><a class="btn btn-small" href="/admin/management-report-prepare.php?type=<?=e($row['report_type'])?>&id=<?=$row['id']?>">ویرایش</a><?php endif?><?php if(ManagementReportsRepository::canReview()&&$row['status']==='submitted'):?><form method="post" onsubmit="return confirm('گزارش تأیید شود؟')"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="submission_id" value="<?=$row['id']?>"><input type="hidden" name="action" value="approve"><input type="hidden" name="return_query" value="<?=e($query)?>"><button class="btn btn-small btn-primary">تأیید</button></form><details><summary class="btn btn-small">برگشت</summary><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="submission_id" value="<?=$row['id']?>"><input type="hidden" name="action" value="return"><input type="hidden" name="return_query" value="<?=e($query)?>"><textarea name="note" rows="3" placeholder="توضیح اصلاحات لازم" required></textarea><button class="btn btn-small">ثبت برگشت</button></form></details><?php endif?></div></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6"><div class="mr-empty">گزارشی مطابق فیلترها پیدا نشد.</div></td></tr><?php endif?></tbody></table></div></section>
